INSERT INTO events (id, session_id, title, event_type, event_date, flyer_banner_url, summary_text, photo_gallery, attendees_count) VALUES 
('event-1', '22222222-2222-2222-2222-222222222222', 'Official AHEFSS Merchandise Creation & Exhibition', 'Merchandise Launch', '2026-03-15', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657213/q0qh8oxqwjdedpg52fyy.png', 'The Elevation Era officially unveiled its customized departmental apparel line, including branded polo shirts, caps, water bottles, pens, and ceramic mugs.', ARRAY['https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657213/q0qh8oxqwjdedpg52fyy.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657218/kjg0qo41mx0dz8rxwsll.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657222/ytuhcpy2fok2va8s6lr6.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657226/bi6ekj9aoygrj7q0e5nm.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657241/zdaxvlyvyosvwmdtpwlj.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657245/yvyhwz4tacysp3nsxxrn.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657269/mpeeallq4aw29xocnium.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657274/betkoouiytt6j5gdgsmh.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657284/gbmzifq0cuurbx186hmy.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657289/o30lahu478gj7auimkmy.png', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657292/dgesaypialtoehueowgy.jpg', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657296/ijjfoottpabimhgfxx7e.jpg', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657300/chl4yh14jqdbwb9yje0x.jpg', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657302/elckqxbb8fdevcejcm9p.jpg']::TEXT[], 250),
('event-2', '22222222-2222-2222-2222-222222222222', 'Pioneer Inauguration & Elevation Symposium', 'Symposium', '2025-11-10', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657310/imrmgxahadt1ul13gjfx.jpg', 'The historic inauguration of the inaugural Elevation Era administration, bringing together departmental faculty, lecturers, and students.', ARRAY['https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657310/imrmgxahadt1ul13gjfx.jpg', 'https://res.cloudinary.com/q9jb9wvk/image/upload/v1786657210/ahwntrie9gopeloq4x0n.jpg']::TEXT[], 400);
